34	pub(super) const CLIENT_ASSERTION_TYPE_JWT_BEARER: &str =
35	    "urn:ietf:params:oauth:client-assertion-type:jwt-bearer";
36	
37	/// Clock skew tolerated on the assertion's time claims (RFC 7523 permits a few minutes;
38	/// 30 seconds covers real-world drift without meaningfully widening the replay window).
39	const CLOCK_TOLERANCE_SECS: u64 = 30;
40	
41	/// Upper bound on a fetched JWK set. Real key sets are a few hundred bytes; the cap only
42	/// exists so a hostile `jwks_uri` host cannot stream an unbounded body into memory. Matches
43	/// the client-metadata document cap.
44	const MAX_JWKS_BYTES: usize = 64 * 1024;
45	
46	#[derive(Debug, Deserialize)]
47	struct ClientAssertionClaims {
48	    iss: String,
49	    sub: String,
50	    jti: Option<String>,
51	}
