102	async fn verify_private_key_jwt(
103	    state: &AppState,
104	    client_id: &str,
105	    metadata: &ClientMetadata,
106	    assertion_type: Option<&str>,
107	    assertion: Option<&str>,
108	) -> Result<(), OAuthTokenError> {
109	    let assertion = assertion.ok_or_else(|| {
110	        invalid_client("client authentication required: missing client_assertion")
111	    })?;
112	    if assertion_type != Some(CLIENT_ASSERTION_TYPE_JWT_BEARER) {
113	        return Err(invalid_client(format!(
114	            "client_assertion_type must be {CLIENT_ASSERTION_TYPE_JWT_BEARER}"
115	        )));
116	    }
117	
118	    let header = jsonwebtoken::decode_header(assertion)
119	        .map_err(|_| invalid_client("client_assertion is not a well-formed JWT"))?;
120	    if header.alg != Algorithm::ES256 {
121	        return Err(invalid_client("client_assertion must be signed with ES256"));
122	    }
123	
124	    let key = resolve_client_key(state, metadata, header.kid.as_deref()).await?;
125	
126	    let issuer = state.config.public_url.trim_end_matches('/').to_string();
127	    let token_url = format!("{issuer}/oauth/token");
128	    let mut validation = Validation::new(Algorithm::ES256);
129	    validation.leeway = CLOCK_TOLERANCE_SECS;
130	    validation.set_audience(&[issuer, token_url]);
131	    validation.set_required_spec_claims(&["exp", "aud"]);
132	
133	    let data = jsonwebtoken::decode::<ClientAssertionClaims>(assertion, &key, &validation)
134	        .map_err(|e| invalid_client(format!("client_assertion rejected: {e}")))?;
135	
136	    if data.claims.iss != client_id || data.claims.sub != client_id {
137	        return Err(invalid_client(
138	            "client_assertion iss and sub must both be the client_id",
139	        ));
140	    }
141	    if data.claims.jti.as_deref().is_none_or(|jti| jti.is_empty()) {
142	        return Err(invalid_client("client_assertion must carry a jti"));
143	    }
144	    Ok(())
145	}
